===== Household =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The single definition of an owner "household": owners sharing the same last name and
 * postcode. The last name is compared case-insensitively with runs of whitespace collapsed
 * to a single space; the postcode is taken as stored. Provides the deterministic identifier
 * shared by the household.
 *
 * <p>The identifier is derived deterministically from the normalized last name and postcode
 * — the first 12 upper-case hex characters of SHA-256 over {@code normalizedLastName + '|' +
 * postcode} — so every owner with the same last name and postcode resolves to the same value
 * regardless of creation order, and no owner-to-owner linking is needed.
 *
 * @see AssignHousehold stamps each owner with its computed identifier.
 * @see EnsureUniqueIdentity blocks a second owner in the same household unless it opts in.
 */
final class Household {

    /** Length of the household identifier, in hex characters. */
    private static final int ID_LENGTH = 12;

    private Household() {
    }

    /** The stable identifier shared by every owner in the household keyed by {@code lastName}
     *  and {@code postcode}. */
    static String id(String lastName, String postcode) {
        String key = normalizeName(lastName) + "|" + (postcode == null ? "" : postcode);
        return Sha256.hex(key, ID_LENGTH);
    }

    /** How many of the given owners belong to the household with {@code householdId}. Owners with a
     *  null or non-matching {@code householdId} are not counted; a null {@code householdId} yields 0. */
    static long size(String householdId, Iterable<Owner> owners) {
        if (householdId == null) {
            return 0;
        }
        long count = 0;
        for (Owner owner : owners) {
            if (householdId.equals(owner.getHouseholdId())) {
                count++;
            }
        }
        return count;
    }

    /** A last name trimmed and lower-cased, with internal whitespace runs collapsed to a single space. */
    private static String normalizeName(String value) {
        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}
===== AssignHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Create-owner step: stamps the new owner with its {@link Household} identifier, computed
 * deterministically from its own last name and postcode. Every owner sharing a last name and
 * postcode therefore resolves to the same {@code householdId} without any owner-to-owner
 * linking. A household is keyed on the postcode, so an owner without one has no household and
 * is left unstamped.
 *
 * <p>Runs after {@link BuildOwner} and before {@link EnsureUniqueIdentity}, so the household
 * identifier is in place for the duplicate check that keys off it.
 */
public class AssignHousehold {

    public void service(@Val Owner owner) {
        String postcode = owner.getPostcode();
        if (postcode == null || postcode.isBlank()) {
            return;
        }
        owner.setHouseholdId(Household.id(owner.getLastName(), postcode));
    }
}
===== Locality =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

/**
 * The single definition of an owner's locality: the canonical region derived from its
 * postcode range first (see {@link Postcode}), falling back to a fixed city-to-region table
 * when the postcode is absent or in no known range. Owners matching neither resolve to
 * {@code "UNKNOWN"}.
 *
 * <p>Lookup only; a pure function of the postcode and city, so the region is computed on read
 * rather than stored.
 */
public final class Locality {

    /** The unknown-region marker returned for any city not in {@link #CITY_REGION}. */
    public static final String UNKNOWN = "UNKNOWN";

    /** City -> canonical region. */
    private static final Map<String, String> CITY_REGION =
            Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    private Locality() {
    }

    /** The canonical region for {@code city} via the city-to-region table alone, or
     *  {@code "UNKNOWN"} when it is not in the table. */
    public static String region(String city) {
        return CITY_REGION.getOrDefault(city, UNKNOWN);
    }

    /** The canonical region for an owner: the postcode's region when its range identifies one,
     *  otherwise the city's region, or {@code "UNKNOWN"} when neither applies. */
    public static String region(String city, String postcode) {
        String byPostcode = Postcode.region(postcode);
        return byPostcode != null ? byPostcode : region(city);
    }
}
